1	package jobs
2	
3	// ProgressState is the summarized state of the registry, in the order of
4	// precedence of what a reader should be told.
5	type ProgressState int
6	
7	const (
8		// ProgressIdle means nothing runs and no failure is unread.
9		ProgressIdle ProgressState = iota
10		// ProgressIndeterminate means something runs but no fair percentage exists.
11		ProgressIndeterminate
12		// ProgressPercent means every running run is measured: Percent is valid.
13		ProgressPercent
14		// ProgressWarning means a cancelled run has not settled yet.
15		ProgressWarning
16		// ProgressError means a failure has not been read yet.
17		ProgressError
18	)
19	
20	// Progress is the whole registry summarized for one reader. It holds only
21	// comparable fields so callers can detect a change with ==.
22	type Progress struct {
23		State ProgressState
24		// Percent is 0..100. It is meaningful when Measured, and 100 for a
25		// ProgressWarning that has no measure.
26		Percent int
27		// Measured reports that every unsettled run has a known size, so Percent is
28		// the weighted completion of all of them.
29		Measured bool
30		// Running counts the unsettled runs, Stopping those among them that were
31		// asked to stop, Unread the failures above the read watermark.
32		Running  int
33		Stopping int
34		Unread   int
35	}
36	
37	// measurable reports whether a run has a known size: it is sealed and holds at
38	// least two targets. A one-target run has no halfway to report.
39	func measurable(r Run) bool { return !r.Open() && r.Total() >= 2 }
40	
41	// Summarize reduces the runs and failures of every context to one Progress.
42	// Failures with a Seq above readThrough are unread. It is pure: no clock, no
43	// registry, no filtering by context.
44	func Summarize(runs []Run, failures []Failure, readThrough uint64) Progress {
45		var p Progress
46		var done, total int
47		allMeasured := true
48		for _, run := range runs {
49			if run.Finished() {
50				continue
51			}
52			p.Running++
53			if run.Cancelled() {
54				p.Stopping++
55			}
56			if measurable(run) {
57				done += run.Done()
58				total += run.Total()
59			} else {
60				allMeasured = false
61			}
62		}
63		for _, f := range failures {
64			if f.Seq > readThrough {
65				p.Unread++
66			}
67		}
68	
69		if p.Running > 0 && allMeasured {
70			p.Measured = true
71			p.Percent = 100 * done / total
72		}
73	
74		switch {
75		case p.Unread > 0:
76			p.State = ProgressError
77		case p.Stopping > 0:
78			p.State = ProgressWarning
79			if !p.Measured {
80				p.Percent = 100
81			}
82		case p.Running == 0:
83			p.State = ProgressIdle
84		case p.Measured:
85			p.State = ProgressPercent
86		default:
87			p.State = ProgressIndeterminate
88		}
89		return p
90	}
91	
92	// LatestFailureSeq returns the highest Seq among failures, 0 for none. It is
93	// the watermark a reader stores once it has shown every failure.
94	func LatestFailureSeq(failures []Failure) uint64 {
95		var latest uint64
96		for _, f := range failures {
97			latest = max(latest, f.Seq)
98		}
99		return latest
100	}
101	
102	// FailuresIn returns a copy of the failures of contextName, in input order.
103	func FailuresIn(failures []Failure, contextName string) []Failure {
104		var out []Failure
105		for _, f := range failures {
106			if f.Context == contextName {
107				out = append(out, f)
108			}
109		}
110		return out
